-- Giorno 21: abbinamento uccelli e cibo. Richiede 003_first_six_games.sql.
-- Modifica esclusivamente la prova: descrizione, foto e link dell’area rimangono intatti.
begin;
update calendar_private.calendar_days
set challenge = $day21${"type":"matching","visual":"food-matching","version":"casone-food-v1","placeholder":false,"title":"A ogni uccello il suo cibo","instructions":"Tocca un uccello, poi scegli il cibo da abbinare. Completa le quattro coppie e controlla il riepilogo prima di confermare.","left":["Assiolo","Gheppio","Airone cenerino","Germano reale"],"right":["Cicala","Topo","Pesce","Germogli e semi"],"solution":[0,1,2,3],"bird_sheet":{"image":"images/giochi/uccelli-giorno-21.png","width":1261,"height":1247,"regions":[[0,0,617.89,579.855],[643.11,0,617.89,586.0899999999999],[0,586.0899999999999,617.89,660.9100000000001],[630.5,623.5,630.5,623.5]]},"food_sheet":{"image":"images/giochi/cibi-giorno-21.png","width":1536,"height":1024,"regions":[[0,0,768,512],[768,0,768,512],[0,512,768,512],[768,512,768,512]]},"diet_notes":["L’assiolo è un piccolo rapace soprattutto insettivoro: caccia cicale, cavallette, coleotteri e altri invertebrati. Nel gioco lo abbiamo abbinato alla cicala, una delle sue possibili prede.","Il gheppio cerca piccole prede nei prati e nei campi. Può restare quasi fermo in volo, nella posizione detta “spirito santo”, prima di scendere verso il terreno. Si nutre spesso di piccoli roditori, tra cui topi e arvicole, ma cattura anche altre prede.","L’airone cenerino cerca il cibo nelle acque basse, fermo in attesa o camminando lentamente. Quando individua una preda, scatta con il collo e la afferra con il lungo becco. Mangia pesci, ma anche anfibi e altre piccole prede. Il pesce illustrato è un esempio generico di pesce d’acqua dolce.","Il germano reale raccoglie semi e parti tenere delle piante in acqua e sul terreno. Per raggiungere il cibo può immergere la parte anteriore del corpo, lasciando la coda in alto. La sua dieta comprende anche piccoli animali: non si nutre soltanto di vegetali."],"hint":"Pensa a dove ciascun uccello cerca il cibo: tra gli insetti, nei prati e nei campi, nell’acqua bassa oppure tra la vegetazione.","explanation":"Nel gioco gli abbinamenti sono assiolo–cicala, gheppio–topo, airone cenerino–pesce e germano reale–germogli e semi. Sono esempi di alimenti che queste specie trovano in natura: ciascun uccello può mangiare anche altro, secondo la stagione e ciò che trova.\n\nIl modo di cercare il cibo cambia da una specie all’altra. L’assiolo caccia soprattutto insetti; il gheppio sorveglia il terreno dall’alto; l’airone cerca prede nell’acqua bassa; il germano raccoglie semi, vegetali e piccoli animali.","sources":[{"title":"Assiolo · LIPU","url":"https://www.lipu.it/uccelli/conoscerli-proteggerli/assiolo"},{"title":"Gheppio · BTO","url":"https://www.bto.org/learn/about-birds/birdfacts/kestrel"},{"title":"Airone cenerino · LIPU","url":"https://www.lipu.it/uccelli/conoscerli-proteggerli/airone-cenerino"},{"title":"Germano reale · Cornell Lab","url":"https://www.allaboutbirds.org/guide/mallard/lifehistory"}]}$day21$::jsonb
where day = 21;
commit;
